// P3 (CREATOR-PACK-SPEC 5.1, 5.1b): Creator presets become ordinary
// keyframes. A preset's tracks (`position.x`, `scale`, `rotation`, ...) are
// generated by the Creator Pack engine (`generatePreset`) and written as
// SET_PROPERTY keyframes in one undo step. Schema 8 has no layer metadata
// field, so the record of what was applied (the preset's own copy, its
// control values and a fingerprint of the keyframes it wrote) is kept in a
// string property `preset` (JSON, read defensively, D-239). When the
// keyframes no longer match the fingerprint they were edited by hand, and the
// controls step aside ("Edited manually") until "Reset to controls".
import type { Command, Easing, Property } from '../core';
import { generatePreset, presetControls } from '../creator-pack/preset';
import {
  expressionReferences,
  parseExpression,
} from '../creator-pack/expression';
import type { Preset } from '../creator-pack/schemas';
import type { ParamSpec as CreatorParam } from '../creator-pack/controls';
import type { ParamSpec } from '../blocks/types';
import { contentHash, stableJson } from '../code-layer/hash';
import type { RenderSource, SceneLayer } from '../render/adapter';

type Composition = RenderSource['composition'];
/** The time a layer's clip starts (its own start without a clip). */
function startOf(composition: Composition, layer: SceneLayer): number {
  for (const track of composition.tracks)
    for (const clip of track.clips)
      if (clip.layerId === layer.id) return clip.startTime;
  return layer.startTime;
}

export const PRESET_PROPERTY = 'preset';
export type TransformKey = 'position' | 'scale' | 'rotation' | 'opacity';
/** Heading groups (spec 5.1b), one per animated transform. */
export const GROUP_OF: Record<TransformKey, string> = {
  position: 'move',
  scale: 'scale',
  rotation: 'rotate',
  opacity: 'opacity',
};
type Channel = { key: TransformKey; axis?: 0 | 1 };
/** A preset track's property name, as a transform channel (or null). */
export function channelOf(property: string): Channel[] | null {
  switch (property) {
    case 'position.x':
    case 'x':
      return [{ key: 'position', axis: 0 }];
    case 'position.y':
    case 'y':
      return [{ key: 'position', axis: 1 }];
    case 'scale':
      return [
        { key: 'scale', axis: 0 },
        { key: 'scale', axis: 1 },
      ];
    case 'scale.x':
      return [{ key: 'scale', axis: 0 }];
    case 'scale.y':
      return [{ key: 'scale', axis: 1 }];
    case 'rotation':
    case 'rotate':
      return [{ key: 'rotation' }];
    case 'opacity':
      return [{ key: 'opacity' }];
    default:
      return null;
  }
}
/** Position and rotation tracks are offsets from the resting value. */
const RELATIVE = new Set<TransformKey>(['position', 'rotation']);

export interface PresetRecord {
  /** Creator library id (`<packId>--<itemId>`). */
  readonly id: string;
  readonly name: string;
  /** The project's own copy of the preset (it never needs the library). */
  readonly preset: Preset;
  readonly params: Record<string, unknown>;
  /** The resting value of every transform it animates, before it applied. */
  readonly base: Partial<Record<TransformKey, number | [number, number]>>;
  /** Fingerprint of the keyframes it wrote, per transform. */
  readonly fingerprint: string;
}

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value);

/** The preset records of a layer (empty when none or unreadable). */
export function readPresets(layer: SceneLayer): PresetRecord[] {
  const property = layer.properties[PRESET_PROPERTY];
  if (!property || property.type !== 'string' || !property.value) return [];
  try {
    const parsed = JSON.parse(property.value) as unknown;
    if (!isRecord(parsed) || !Array.isArray(parsed.presets)) return [];
    return parsed.presets.filter(
      (item): item is PresetRecord =>
        isRecord(item) &&
        typeof item.id === 'string' &&
        typeof item.name === 'string' &&
        isRecord(item.preset) &&
        Array.isArray((item.preset as { tracks?: unknown }).tracks) &&
        isRecord(item.params) &&
        isRecord(item.base) &&
        typeof item.fingerprint === 'string',
    );
  } catch {
    return [];
  }
}
/** The transforms a preset animates. */
export function keysOf(preset: Preset): TransformKey[] {
  const keys = new Set<TransformKey>();
  for (const track of preset.tracks)
    for (const channel of channelOf(track.property) ?? [])
      keys.add(channel.key);
  return [...keys];
}
/** Tracks this editor cannot animate (refused with their names). */
export function unsupportedTracks(preset: Preset): string[] {
  return preset.tracks
    .map((track) => track.property)
    .filter((property) => !channelOf(property));
}

type Frame = {
  time: number;
  value: number | [number, number];
  easing?: Easing;
};
const fingerprintOf = (frames: Record<string, unknown>) =>
  contentHash(stableJson(frames));
/** The current keyframes of the given transforms (for the fingerprint). */
function currentFrames(layer: SceneLayer, keys: readonly TransformKey[]) {
  const out: Record<string, unknown> = {};
  for (const key of keys) {
    const property = layer.transform[key];
    out[key] = property.animated
      ? property.keyframes.map((frame) => ({
          time: Math.round(frame.time * 1e6) / 1e6,
          value: frame.value,
          easing: frame.easing ?? 'linear',
        }))
      : [];
  }
  return out;
}
/** True when the keyframes it wrote were changed since (spec 5.1b). */
export function editedManually(layer: SceneLayer, record: PresetRecord) {
  return (
    fingerprintOf(currentFrames(layer, keysOf(record.preset))) !==
    record.fingerprint
  );
}

const restingOf = (layer: SceneLayer, key: TransformKey) => {
  const value = layer.transform[key].value as number | readonly number[];
  return typeof value === 'number'
    ? value
    : ([value[0]!, value[1]!] as [number, number]);
};
const valueAt = (
  keys: readonly { t: number; v: number }[],
  time: number,
): number => {
  if (time <= keys[0]!.t) return keys[0]!.v;
  for (let i = 1; i < keys.length; i++) {
    const a = keys[i - 1]!,
      b = keys[i]!;
    if (time <= b.t) return a.v + ((b.v - a.v) * (time - a.t)) / (b.t - a.t);
  }
  return keys[keys.length - 1]!.v;
};
const round = (value: number) => Math.round(value * 1e6) / 1e6;

/** The keyframes a preset generates for a layer, per transform. */
export function presetFrames(
  preset: Preset,
  params: Record<string, unknown>,
  base: PresetRecord['base'],
  start: number,
  dims: { W: number; H: number; w: number; h: number },
): Partial<Record<TransformKey, Frame[]>> {
  const tracks = generatePreset(preset, params, dims);
  const byKey = new Map<
    TransformKey,
    { axis?: 0 | 1; keys: { t: number; v: number; ease: string }[] }[]
  >();
  for (const track of tracks) {
    const channels = channelOf(track.property);
    if (!channels) throw new Error(`Unsupported property ${track.property}.`);
    for (const channel of channels)
      byKey.set(channel.key, [
        ...(byKey.get(channel.key) ?? []),
        {
          ...(channel.axis !== undefined ? { axis: channel.axis } : {}),
          keys: track.keys,
        },
      ]);
  }
  const out: Partial<Record<TransformKey, Frame[]>> = {};
  for (const [key, channels] of byKey) {
    const times = [
      ...new Set(channels.flatMap((c) => c.keys.map((k) => round(k.t)))),
    ].sort((a, b) => a - b);
    const rest = base[key];
    out[key] = times.map((t) => {
      const ease =
        channels.flatMap((c) => c.keys).find((k) => round(k.t) === t)?.ease ??
        'linear';
      const pick = (axis?: 0 | 1) => {
        const channel = channels.find((c) => c.axis === axis);
        const restValue =
          rest === undefined
            ? 0
            : typeof rest === 'number'
              ? rest
              : rest[axis ?? 0]!;
        if (!channel) return restValue;
        const generated = valueAt(channel.keys, t);
        const value = RELATIVE.has(key) ? restValue + generated : generated;
        return key === 'opacity' ? Math.min(1, Math.max(0, value)) : value;
      };
      const value: Frame['value'] =
        key === 'position' || key === 'scale'
          ? [round(pick(0)), round(pick(1))]
          : round(pick());
      return {
        time: round(start + t),
        value,
        ...(ease !== 'linear' ? { easing: ease as Easing } : {}),
      };
    });
  }
  return out;
}

const transformCommand = (
  compositionId: string,
  layer: SceneLayer,
  key: TransformKey,
  frames: Frame[],
): Command =>
  ({
    type: 'SET_PROPERTY',
    compositionId,
    layerId: layer.id,
    target: { kind: 'transform', key },
    property: transformProperty(layer, key, frames),
  }) as Command;
function transformProperty(
  layer: SceneLayer,
  key: TransformKey,
  frames: Frame[],
): Property {
  const current = layer.transform[key] as unknown as Record<string, unknown>;
  return {
    ...current,
    value: frames[0]?.value ?? current.value,
    animated: frames.length > 0,
    keyframes: frames,
  } as unknown as Property;
}
const presetCommand = (
  compositionId: string,
  layer: SceneLayer,
  records: readonly PresetRecord[],
): Command =>
  ({
    type: 'SET_PROPERTY',
    compositionId,
    layerId: layer.id,
    target: { kind: 'property', key: PRESET_PROPERTY },
    property: {
      type: 'string',
      value: records.length
        ? JSON.stringify({ version: 1, presets: records })
        : '',
      animated: false,
      keyframes: [],
      constraints: [],
    },
  }) as Command;

export function dimensionsOf(composition: Composition, layer: SceneLayer) {
  const number = (key: string) => {
    const property = layer.properties[key];
    return property?.type === 'number' && property.value > 0
      ? property.value
      : null;
  };
  return {
    W: composition.width,
    H: composition.height,
    w: number('width') ?? composition.width / 3,
    h: number('height') ?? composition.height / 3,
  };
}

/**
 * Applies (or re-applies) a preset to a layer: its keyframes from the clip's
 * start and the updated record. A preset that animates a transform another
 * preset animates replaces that one. Returns the commands (one transaction).
 */
export function presetCommands(
  composition: Composition,
  layer: SceneLayer,
  apply: {
    id: string;
    name: string;
    preset: Preset;
    params: Record<string, unknown>;
  },
): Command[] {
  const unsupported = unsupportedTracks(apply.preset);
  if (unsupported.length)
    throw new Error(
      `This preset animates ${unsupported.join(', ')}, which a layer cannot animate yet.`,
    );
  const keys = keysOf(apply.preset);
  const records = readPresets(layer);
  const previous = records.find((item) => item.id === apply.id);
  const others = records.filter(
    (item) =>
      item.id !== apply.id &&
      !keysOf(item.preset).some((key) => keys.includes(key)),
  );
  // Resting values: kept from the first application, so re-generating with
  // new control values never compounds the offsets.
  const base: Record<string, number | [number, number]> = {};
  for (const key of keys) {
    const kept =
      previous?.base[key] ??
      records.find((item) => item.base[key] !== undefined)?.base[key];
    base[key] = kept ?? restingOf(layer, key);
  }
  const start = startOf(composition, layer);
  const frames = presetFrames(
    apply.preset,
    apply.params,
    base,
    start,
    dimensionsOf(composition, layer),
  );
  const fingerprint = fingerprintOf(
    Object.fromEntries(
      keys.map((key) => [
        key,
        (frames[key] ?? []).map((frame) => ({
          time: frame.time,
          value: frame.value,
          easing: frame.easing ?? 'linear',
        })),
      ]),
    ),
  );
  const record: PresetRecord = {
    id: apply.id,
    name: apply.name,
    preset: apply.preset,
    params: apply.params,
    base,
    fingerprint,
  };
  return [
    ...keys.map((key) =>
      transformCommand(composition.id, layer, key, frames[key] ?? []),
    ),
    presetCommand(composition.id, layer, [...others, record]),
  ];
}

/** Controls of a preset per heading group (spec 5.1b), plus the advanced. */
export function presetGroups(preset: Preset): {
  groups: { group: string; controls: CreatorParam[] }[];
  advanced: CreatorParam[];
} {
  const controls = presetControls(preset);
  const placed = new Set<string>();
  const groups: { group: string; controls: CreatorParam[] }[] = [];
  for (const key of ['position', 'scale', 'rotation', 'opacity'] as const) {
    const tracks = preset.tracks.filter((track) =>
      (channelOf(track.property) ?? []).some((c) => c.key === key),
    );
    if (!tracks.length) continue;
    const refs = new Set<string>();
    for (const track of tracks)
      for (const k of track.keys)
        if (typeof k.v === 'string')
          for (const name of expressionReferences(parseExpression(k.v)))
            refs.add(name);
    const mine = controls.filter(
      (control) =>
        refs.has(control.name) &&
        !placed.has(control.name) &&
        control.group !== 'advanced',
    );
    for (const control of mine) placed.add(control.name);
    groups.push({ group: GROUP_OF[key], controls: mine });
  }
  return {
    groups,
    advanced: controls.filter((control) => !placed.has(control.name)),
  };
}

const EASINGS = ['linear', 'ease-in', 'ease-out', 'ease-in-out', 'hold'];
/** A Creator control as a form control (point and range are not shown). */
export function formSpec(
  control: CreatorParam,
  label: string,
): ParamSpec | null {
  switch (control.type) {
    case 'number':
    case 'angle':
      return {
        name: control.name,
        label,
        type: 'number',
        min: control.min,
        max: control.max,
        step: control.step,
        default: control.default,
      };
    case 'color':
      return {
        name: control.name,
        label,
        type: 'color',
        default: control.default,
      };
    case 'text':
      return {
        name: control.name,
        label,
        type: 'text',
        default: control.default,
      };
    case 'bool':
      return {
        name: control.name,
        label,
        type: 'bool',
        default: control.default,
      };
    case 'select':
      return {
        name: control.name,
        label,
        type: 'select',
        default: control.default,
        options: control.options,
      };
    case 'easing':
      return {
        name: control.name,
        label,
        type: 'select',
        default: String(control.default),
        options: EASINGS,
      };
    default:
      return null;
  }
}

/** Removes every preset record (Reset keeps them; this is "Remove"). */
export function clearPresetCommand(compositionId: string, layer: SceneLayer) {
  return presetCommand(compositionId, layer, []);
}

// --- Simple view for hand- or AI-made keyframes (spec 5.1b) ---------------

export interface SimpleTrack {
  readonly key: TransformKey;
  readonly from: number | [number, number];
  readonly to: number | [number, number];
  readonly duration: number;
  readonly delay: number;
  readonly easing: string;
}
/** The keyframed transforms no preset record covers, as From/To tracks. */
export function simpleTracks(
  composition: Composition,
  layer: SceneLayer,
): SimpleTrack[] {
  const covered = new Set(
    readPresets(layer)
      .filter((record) => !editedManually(layer, record))
      .flatMap((record) => keysOf(record.preset)),
  );
  const start = startOf(composition, layer);
  const list: SimpleTrack[] = [];
  for (const key of ['position', 'scale', 'rotation', 'opacity'] as const) {
    const property = layer.transform[key];
    if (covered.has(key) || !property.animated || property.keyframes.length < 2)
      continue;
    const frames = property.keyframes;
    const first = frames[0]!,
      last = frames[frames.length - 1]!;
    const easing = first.easing;
    list.push({
      key,
      from: first.value as number | [number, number],
      to: last.value as number | [number, number],
      duration: round(last.time - first.time),
      delay: round(Math.max(0, first.time - start)),
      easing:
        typeof easing === 'string' ? easing : easing ? 'custom' : 'linear',
    });
  }
  return list;
}
/** Rewrites one keyframed transform from its simple view (one step). */
export function simpleCommand(
  composition: Composition,
  layer: SceneLayer,
  key: TransformKey,
  change: Partial<Omit<SimpleTrack, 'key'>>,
): Command {
  const property = layer.transform[key];
  const frames = property.keyframes as Frame[];
  const start = startOf(composition, layer);
  const first = frames[0]!,
    last = frames[frames.length - 1]!;
  const span = last.time - first.time || 1;
  const duration = Math.max(0.01, change.duration ?? span);
  const delay = Math.max(0, change.delay ?? first.time - start);
  const next = frames.map((frame, index): Frame => {
    const time = round(
      start + delay + ((frame.time - first.time) / span) * duration,
    );
    let value = frame.value;
    if (index === 0 && change.from !== undefined) value = change.from;
    if (index === frames.length - 1 && change.to !== undefined)
      value = change.to;
    if (key === 'opacity' && typeof value === 'number')
      value = Math.min(1, Math.max(0, value));
    const easing =
      change.easing !== undefined && index < frames.length - 1
        ? change.easing === 'linear'
          ? undefined
          : (change.easing as Easing)
        : frame.easing;
    return { time, value, ...(easing ? { easing } : {}) };
  });
  return transformCommand(composition.id, layer, key, next);
}
